  ((select id from trips where name = 'Scozia 2026'), '2026-08-11', 'relax', 'The Mustard Seed Restaurant (Inverness)', 'nel_piano', '20:15:00', null, '21:15:00', 'partenza', 'ChIJxaoRsVNxj0gRNxsTTBxOr2w', 'https://www.google.com/maps/place/?q=place_id:ChIJxaoRsVNxj0gRNxsTTBxOr2w', null, null, '{"raw":"12:00-22:00 (martedi)"}'::jsonb, 'Ristorante sul fiume Ness, ottime viste. Cena tardiva rispetto alla finestra ideale (18:00-19:30): con il trekking del pomeriggio non e possibile arrivare prima.', '+44 1463 220220', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-12', 'relax', 'No.1 Bistro (Wick) - pranzo', 'nel_piano', '12:00:00', null, '13:00:00', 'partenza', 'ChIJP9l9fLXXmkgR5toM25Bxmz4', 'https://www.google.com/maps/place/?q=place_id:ChIJP9l9fLXXmkgR5toM25Bxmz4', null, null, '{"raw":"11:00-13:45 e 17:30-20:30 (mercoledi)"}'::jsonb, 'Bistrot molto apprezzato nel centro di Wick, servizio pranzo entro le 13:45.', '+44 1955 602323', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-12', 'relax', 'No.1 Bistro (Wick) - cena', 'nel_piano', '18:30:00', null, '19:30:00', 'partenza', 'ChIJP9l9fLXXmkgR5toM25Bxmz4', 'https://www.google.com/maps/place/?q=place_id:ChIJP9l9fLXXmkgR5toM25Bxmz4', null, null, '{"raw":"11:00-13:45 e 17:30-20:30 (mercoledi)"}'::jsonb, 'Stesso locale del pranzo, turno cena entro le 20:30. Dopo cena, ~20 min di guida fino a Beyond North Cabins.', '+44 1955 602323', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-13', 'relax', 'Red Pepper (Thurso) - pranzo', 'nel_piano', '12:00:00', null, '13:00:00', 'partenza', 'ChIJxXzH-Ku4mkgRtac1qTh5TPQ', 'https://www.google.com/maps/place/?q=place_id:ChIJxXzH-Ku4mkgRtac1qTh5TPQ', null, null, '{"raw":"12:00-14:00 e 17:00-20:30 (mercoledi)"}'::jsonb, 'Ristorante nel centro di Thurso, dentro l''Holborn Hotel. Buoni voti, anche opzioni senza glutine.', '+44 1847 892771', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-14', 'relax', 'Sea Breezes (Portree) - pranzo', 'nel_piano', '12:30:00', null, '13:15:00', 'partenza', 'ChIJw0BBvC0yjEgRNVtV9vap2a0', 'https://www.google.com/maps/place/?q=place_id:ChIJw0BBvC0yjEgRNVtV9vap2a0', null, null, '{"raw":"12:00-14:00 e 17:30-21:00 (venerdi)"}'::jsonb, 'Ristorante di pesce molto popolare sul porto di Portree; consigliato arrivare presto, si formano code.', '+44 1478 612016', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-14', 'relax', 'The Bistro at Atholl House (Dunvegan) - cena', 'nel_piano', '18:00:00', null, '19:20:00', 'partenza', 'ChIJL1MQW91NjEgRyrzKxb3IWm8', 'https://www.google.com/maps/place/?q=place_id:ChIJL1MQW91NjEgRyrzKxb3IWm8', null, null, '{"raw":"17:00-19:30 (venerdi, ultimo ordine)"}'::jsonb, 'Piccolo bistrot vicino a Tidal Reach, cucina locale. Chiude alle 19:30: prenotare in anticipo. Dopo cena, ~20 min fino a Neist Point per il tramonto.', '+44 1470 521810', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-15', 'relax', 'The Geographer (Fort William) - pranzo', 'nel_piano', '13:00:00', null, '14:00:00', 'partenza', 'ChIJkfh3NqvMjkgRHmPixSmuz68', 'https://www.google.com/maps/place/?q=place_id:ChIJkfh3NqvMjkgRHmPixSmuz68', null, null, '{"raw":"12:00-14:00 e 17:00-21:00 (sabato)"}'::jsonb, 'Bistrot molto ben valutato sulla via principale di Fort William.', '+44 1397 705011', false, null),
  ((select id from trips where name = 'Scozia 2026'), '2026-08-15', 'relax', 'Olive & Stone (DoubleTree Edinburgh Airport) - cena', 'nel_piano', '20:45:00', null, '21:30:00', null, null, null, null, null, '{"raw":"Aperto fino alle 22:00"}'::jsonb, 'Ristorante dentro il DoubleTree stesso: comodo dopo il check-in tardivo. Cena oltre la finestra ideale (18:00-19:30), inevitabile per via della riconsegna auto alle 20:00-20:30.', null, false, null);

insert into trip_days (trip_id, day, summary, overnight_stay_event_id)
select (select id from trips where name = 'Scozia 2026'), '2026-08-10'::date, 'Arrivo serale a Edimburgo. Nessuna tappa turistica in programma: solo atterraggio e check-in tardo vicino all''aeroporto, in vista della partenza verso nord del giorno dopo.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-10'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-11'::date, 'Da Edimburgo verso le Highlands centrali, passando per Stirling e il Cairngorms National Park. Prima notte a Inverness, la capitale delle Highlands scozzesi.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-11'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-12'::date, 'Dalle Highlands alla costa nord-orientale del Caithness, fino a John o'' Groats — il punto più a nord-est della Scozia continentale. Notte vicino Wick.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-12'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-13'::date, 'Lungo la costa nord (North Coast 500) verso ovest, tra spiagge, riserve naturali e distillerie, fino a Ullapool. Da lì attraversamento verso l''Isola di Skye, con arrivo a tarda sera: prima di due notti sull''isola.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-13'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-14'::date, 'Giornata intera sull''Isola di Skye, tra i paesaggi più spettacolari della Scozia: trekking, cascate, distillerie e tramonto sulla costa occidentale. Seconda notte a Skye.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-14'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-15'::date, 'Da Skye verso Edimburgo attraverso le Highlands occidentali, con soste a Eilean Donan Castle e Glencoe. Rientro serale in città per l''ultima notte prima della partenza.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-15'::date limit 1)
union all
select (select id from trips where name = 'Scozia 2026'), '2026-08-16'::date, 'Giorno di partenza: volo di rientro da Edimburgo.', (select id from events where trip_id = (select id from trips where name = 'Scozia 2026') and category = 'alloggio' and day = '2026-08-16'::date limit 1)
on conflict (trip_id, day) do update set summary = excluded.summary, overnight_stay_event_id = excluded.overnight_stay_event_id;
